"""Lower-secondary problems: constraints, inverse reasoning, and clear geometry."""
from itertools import permutations
import sympy as s
from .targeted_math import checked,constant,system,finite,m,pair,rp,solve_certificate

a,b,c,x=s.symbols('a b c x',real=True)

def inverse_ratio(r,level='hard'):
    u=r.randint(2,6);v=u+r.randint(2,5);k=r.randint(3,9);move=r.randint(1,k);p=u*k;q=v*k;ratio=s.Rational(p+move,q-move);value=p+q
    return checked(f'Kotak A dan B semula memiliki kelereng dengan rasio {u}:{v}. Setelah {move} kelereng dipindahkan dari B ke A, rasio A:B menjadi {m(ratio)}:1. Berapa jumlah kelereng kedua kotak?',value,f'Tulis banyak semula a,b. Data memberi va=ub dan (a+{move})/(b-{move})={ratio}. Eliminasi menentukan a={p}, b={q}. Jumlah {value}.','v2_rasio_transfer_inverse',level,system(['a','b'],[v*a-u*b,a+move-ratio*(b-move)],a+b,[a,b-move]))

def shifted_mean(r,level='hard'):
    n=r.randint(9,25);mean=r.randint(40,75);old=r.randint(10,30);delta=r.randint(1,3);new=old+n*delta;remove=r.randint(20,70);value=s.Rational(n*mean-remove,n-1)
    return checked(f'Rata-rata n nilai semula {mean}. Setelah satu nilai {old} diganti {new}, rata-rata naik {delta}. Data kemudian dikembalikan ke keadaan semula. Satu nilai {remove} dihapus. Berapa rata-rata sisanya?',value,f'Perubahan jumlah {new-old} sama dengan n×{delta}, jadi n={n}. Jumlah semula {n*mean}; setelah penghapusan jumlah {n*mean-remove}, banyak {n-1}. Rata-rata {value}.','v2_pemusatan_koreksi_inverse',level,system(['a'],[delta*a-new+old],(a*mean-remove)/(a-1),[a-1]))

def generate(grade,bab,code,level,r):
    A=r.randint(2,8);B=r.randint(2,9);C=r.randint(1,7);U=r.randint(3,12);V=r.randint(2,8);T=r.randint(3,7)
    if grade==7:
        if bab==1:
            if level=='medium':return constant(f'Suhu mula-mula -{U}°C. Suhu naik {A}°C tiap jam selama {B} jam, lalu turun {C}°C. Berapa suhu akhirnya?',-U+A*B-C,f'Kenaikan total {A*B}°C. Suhu akhir -{U}+{A*B}-{C}={-U+A*B-C}.','v2_integer_perubahan_bertahap',level)
            p=-U;q=V;extra=2*r.randint(2,7);root=p-extra//2;d=q-p+extra
            return checked(f'Bilangan bulat x berjarak total {d} satuan dari titik {p} dan {q} pada garis bilangan, yaitu |x-({p})|+|x-{q}|={d}. Jika x<{p}, berapa nilai {A}-2x?',A-2*root,f'Pada selang antara kedua titik jumlah jarak hanya {q-p}, sehingga x di luar selang. Syarat x<{p} memilih sisi kiri: ({p}-x)+({q}-x)={d}, jadi x={root}. Nilai {A}-2x={A-2*root}.','v2_integer_jarak_cabang',level,system(['a'],[p-a+q-a-d],A-2*a,[p-a]))
        if bab==2:
            if code=='A':
                lo=-r.randint(3,8);hi=r.randint(4,10);lower=s.Rational(3*lo+1,3);upper=s.Rational(4*hi-1,4);mod=r.randint(2,4);vals=[j for j in range(lo,hi+1) if lower<j<upper and j%mod!=0];guards=[s.Piecewise((0,x>lower),(1,True)),s.Piecewise((0,x<upper),(1,True)),s.Piecewise((0,s.Ne(s.Mod(x,mod),0)),(1,True))]
                return checked(f'Tentukan jumlah semua bilangan bulat di antara {m(lower)} dan {m(upper)}, kedua batas tidak disertakan, yang bukan kelipatan {mod}.',sum(vals),f'Tentukan dahulu batas bulat dari dua pecahan. Lalu keluarkan kelipatan {mod}. Daftar tersisa {vals}; jumlah {sum(vals)}.','v2_rasional_batas_penyaringan',level,finite(['x'],[[lo,hi]],guards,x,'sum'))
            if level=='easy':return constant(f'Bilangan manakah yang lebih besar: {m(-s.Rational(U,10))} atau {m(s.Rational(V,10))}? Pilih nilainya.',s.Rational(V,10),'Bilangan positif lebih besar daripada bilangan negatif.','v2_rasional_tanda',level)
            values=[s.Rational(A,B)-s.Rational(C,U),-s.Rational(B,U)+s.Rational(A,V),s.Rational(C,V)-s.Rational(U,B)];query=s.Max(a,b,c)-s.Min(a,b,c)
            return checked(f'Diberikan P={A}/{B}-{C}/{U}, Q=-{B}/{U}+{A}/{V}, dan R={C}/{V}-{U}/{B}. Tentukan selisih nilai terbesar dan terkecil.',max(values)-min(values),f'Samakan penyebut pada masing-masing bentuk dan bandingkan tanda serta nilainya. Urutan {sorted(values)}; selisih {max(values)-min(values)}.','v2_rasional_operasi_pengurutan',level,system(['a','b','c'],[a-values[0],b-values[1],c-values[2]],query))
        if bab==3:
            if level=='medium':return constant(f'Rasio buku fiksi:nonfiksi adalah {A}:{B}. Jumlahnya {U*(A+B)}. Jika {C} buku nonfiksi dipinjam, berapa nonfiksi yang masih tersedia?',B*U-C,f'Satu bagian {U}; nonfiksi {B*U}. Setelah dipinjam tersisa {B*U-C}.','v2_rasio_bagian_perubahan',level)
            if code=='A':return inverse_ratio(r)
            scale=r.choice([100,200,250,500]);width=U;length=U+V;area=width*length;difference=V;value=2*(width+length)*scale/100
            return checked(f'Denah persegi panjang berskala 1:{scale} memiliki luas {area} cm² dan selisih panjang dengan lebarnya {difference} cm. Berapa keliling sebenarnya dalam meter?',s.Rational(2*(width+length)*scale,100),f'Tulis lebar x, panjang x+{difference}. Persamaan x(x+{difference})={area} memberi akar positif {width}. Panjang {length}; keliling denah {2*(width+length)} cm. Konversi skala ke meter memberi {value}.','v2_skala_dimensi_inverse',level,system(['a','b'],[a*b-area,a-b-difference],2*(a+b)*s.Rational(scale,100),[a,b]))
        if bab==4:
            if code=='C':return constant(f'Sewa sepeda berbiaya tetap {rp(A*1000)} ditambah {rp(B*1000)} tiap jam. Berapa biaya sewa {U} jam dalam rupiah?',1000*(A+B*U),f'Model biaya {A*1000}+{B*1000}t; pada t={U} menjadi {1000*(A+B*U)}.','v2_model_aljabar_langsung',level)
            p=r.randint(2,6);q=p+r.randint(2,5);alpha=A;beta=B;coef=alpha+beta;const=p*alpha+q*beta;query=(a-b)*T+a*b
            if code=='A':
                return checked(rf'Bentuk $a(x+{p})+b(x+{q})$ mempunyai koefisien x sebesar {coef} dan konstanta {const}. Tentukan $(a-b){T}+ab$.',query.subs({a:alpha,b:beta}),f'Kembangkan dan kelompokkan: (a+b)x+({p}a+{q}b). Dua unsur memberi a+b={coef} dan {p}a+{q}b={const}, sehingga a={alpha},b={beta}. Evaluasi ekspresi hasil {query.subs({a:alpha,b:beta})}.','v2_unsur_aljabar_parameter',level,system(['a','b'],[a+b-coef,p*a+q*b-const],query))
            total=alpha*p+beta*q;diff=alpha-beta
            return checked(rf'Dua bentuk $P(x)=ax+{p}$ dan $Q(x)=bx+{q}$ memenuhi koefisien x pada P-Q sebesar {diff}, serta $P({p})+Q({q})={total+p+q}$. Tentukan $P({T})Q({T})$.',(alpha*T+p)*(beta*T+q),f'Operasi P-Q memberi a-b={diff}. Persamaan nilai memberi {p}a+{q}b={total}. Maka a={alpha}, b={beta}. Substitusikan ke P({T}),Q({T}) lalu kalikan; hasil {(alpha*T+p)*(beta*T+q)}.','v2_operasi_aljabar_rekonstruksi',level,system(['a','b'],[a-b-diff,p*a+q*b-total],(a*T+p)*(b*T+q)))
        if bab==5:
            if code=='A':
                if level=='medium':return constant(f'Dua garis sejajar dipotong sebuah garis. Salah satu sudut sehadap  {U*5}°. Tentukan besar sudut pelurus sudut sehadap pasangannya.',180-U*5,f'Sudut sehadap sama besar {U*5}°. Pelurusnya 180-{U*5}={180-U*5}°.','v2_sudut_sejajar_pelurus',level)
                p=r.randint(4,14);q=r.randint(5,15);t=r.randint(12,20);last=180-(2*t+p)-(3*t+q)
                value=s.Rational(2*t+p,2)+3*t+q
                return checked(rf'Segitiga ABC mempunyai sudut A=$(2x+{p})^\circ$, B=$(3x+{q})^\circ$, dan C={m(last)}°. Garis bagi sudut A memotong BC di D. Tentukan besar sudut luar di D yang berpelurus dengan sudut ADB, dalam derajat.',value,f'Jumlah sudut segitiga menentukan x={t}. Pada segitiga ABD, sudut A dibagi dua dan sudut B tetap. Sudut luar di D sama dengan A/2+B={value}.','v2_sudut_garis_bagi_luar',level,system(['a'],[2*a+p+3*a+q+last-180],(2*a+p)/2+3*a+q))
            width=U;factor=r.randint(2,4);extra=r.randint(2,6);length=V+10
            if level=='medium':return constant(f'Dua persegi panjang sebangun. Sisi pendek kecil {width}, sisi pendek besar {factor*width}. Jika keliling kecil {2*(length+width)} cm, berapa sisi panjang besar?',factor*length,f'Panjang kecil={2*(length+width)}/2-{width}={length}. Faktor skala {factor}, sehingga panjang besar {factor*length}.','v2_sebangun_keliling_rutin',level)
            if code=='C':
                small=U+2;ratio=r.randint(2,4);big=small*ratio;offset=r.randint(1,4);value=ratio*(small+offset)
                return checked(f'Segitiga ABC sebangun DEF, dengan AB berpadanan DE dan BC dengan EF. Diketahui DE-AB={big-small}, BC-AB={offset}, serta keliling ABC={3*small+offset+V} dan AC=AB+{V}. Rasio DE:AB={ratio}:1. Tentukan EF.',value,f'Dari DE={ratio}AB dan selisihnya, AB={small}. Maka BC={small+offset}. Kesebangunan memberi EF={ratio}BC={value}; keliling konsisten dengan AC={small+V}.','v2_segitiga_sebangun_dimensi',level,system(['a','b'],[b-ratio*a,b-a-big+small],ratio*(a+offset),[a,b]))
            # Corresponding widths, plus difference of lengths, reconstruct both figures.
            return checked(f'Dua persegi panjang sebangun dengan lebar {width} cm dan {factor*width} cm. Selisih panjangnya {length*(factor-1)} cm. Pada persegi panjang besar, pita dipasang mengelilingi bangun dengan celah {extra} cm. Berapa panjang pita?',2*factor*(length+width)-extra,f'Rasio sisi {factor}; jika panjang kecil p, selisih ({factor}-1)p={length*(factor-1)}, maka p={length}. Panjang besar {factor*length}; keliling besar {2*factor*(length+width)}. Kurangi celah {extra}, hasil {2*factor*(length+width)-extra}.','v2_sebangun_selisih_keliling',level,system(['a','b'],[b-factor*a,b-a-length*(factor-1)],2*(b+factor*width)-extra,[a,b]))
        if code in ['A','B']:
            if code=='A':
                group1=5*U;group2=5*V;responses=4*U+3*V;unreturned=U+2*V;query=(a/s.Integer(5)-2*b/s.Integer(5))/(a+b)
                return checked(f'Survei dibagikan ke dua kelompok, total {group1+group2} siswa. Kelompok I mengembalikan 4/5 formulirnya, kelompok II 3/5; jumlah kembali {responses}. Semua siswa menerima satu formulir. Berapa selisih banyak formulir tidak kembali dari kelompok I dan II, dibagi total siswa?',s.Rational(U-2*V,group1+group2),f'Tulis besar kelompok a,b. Dari a+b={group1+group2} dan 4a/5+3b/5={responses}, diperoleh a={group1},b={group2}. Yang tidak kembali a/5={U}, 2b/5={2*V}; selisih dibagi total {s.Rational(U-2*V,group1+group2)}.','v2_investigasi_respons_kelompok',level,system(['a','b'],[a+b-group1-group2,4*a/5+3*b/5-responses],query,[a,b]))
            count=[r.randint(2,8) for _ in range(4)];value=count[0]+count[2]
            if level=='medium':return constant(f'Dari {sum(count)} isian survei: {count[0]} mencatat banyak saudara, {count[1]} warna favorit, {count[2]} jumlah buku, {count[3]} peringkat lomba. Berapa isian yang termasuk kuantitatif diskret?',value,f'Banyak saudara dan jumlah buku adalah hitungan diskret; total {count[0]}+{count[2]}={value}.','v2_data_jenis_hitung',level)
            swapped=r.randint(1,min(count[0],count[1]));total=sum(count);true=count[0]+count[2]
            return checked(f'Ada {count[0]} catatan banyak saudara, {count[1]} warna favorit, {count[2]} jumlah buku, dan {count[3]} peringkat lomba. Sistem menandai semua hitungan sebagai kuantitatif diskret, tetapi keliru menukar label {swapped} catatan banyak saudara dengan {swapped} catatan warna favorit. Setelah label diperbaiki, berapa selisih banyak catatan yang benar-benar diskret dan yang bukan diskret?',2*true-total,f'Warna nominal dan peringkat ordinal bukan kuantitatif diskret. Banyak saudara dan buku diskret: {true}. Pertukaran label tidak mengubah isi data. Kelompok bukan diskret {total-true}; selisih {2*true-total}.','v2_jenis_data_audit_salah_label',level,system(['a','b'],[a-count[0]-count[2],a+b-total],a-b))
        if code=='E':
            total=12*U;left=30*A;remainder=U*(12-A);diff=2*B+remainder%2
            return checked(f'Diagram lingkaran memuat {total} siswa dalam tiga klub. Klub A memiliki sudut pusat {left}°. Selisih jumlah anggota B dan C adalah {diff}, dengan B lebih banyak. Berapa sudut pusat B?',s.Rational(remainder+diff,2)*360/total,f'Anggota A={U*A}; sisa B+C={remainder}. Bersama B-C={diff}, diperoleh B={(remainder+diff)//2}, lalu sudut B=360B/{total}.','v2_lingkaran_kelompok_inverse',level,system(['a','b'],[a+b-remainder,a-b-diff],360*a/total,[a,b]))
        # Compare two display designs with normalized axes rather than decoration.
        first=r.randint(30,70);last=first+r.randint(5,20);baseline=first-r.randint(2,10);actual=s.Rational(last-first,first)*100;apparent=s.Rational(last-baseline,first-baseline)
        return constant(f'Data anggota klub naik dari {first} menjadi {last}. Diagram I memakai batang mulai nol; diagram II memotong sumbu pada {baseline}. Untuk melaporkan perubahan nyata, berapa persentase kenaikan berdasarkan data, bukan perbandingan tinggi batang diagram II?',actual,f'Gunakan nilai asli: ({last}-{first})/{first}×100={actual}%. Sumbu dipotong mengubah perbandingan tinggi batang, sehingga diagram mulai nol lebih tepat untuk membandingkan besar kategori.','v2_pilih_diagram_sumbu_persen',level)
    if grade==8:
        if bab==1:
            if code=='A':
                return checked(rf'Bilangan bulat a,b memenuhi $2^{{a+b}}={2**(A+B)}$ dan $2^{{2a-b}}={s.latex(s.Rational(2)**(2*A-B))}$. Tentukan $a^2-b^2$.',A*A-B*B,f'Samakan pangkat: a+b={A+B}, 2a-b={2*A-B}. Eliminasi memberi a={A}, b={B}; selisih kuadrat {A*A-B*B}.','v2_pangkat_sistem_eksponen',level,system(['a','b'],[a+b-A-B,2*a-b-2*A+B],a*a-b*b))
            if code=='C':
                exp=r.randint(3,8);exp2=r.randint(1,3);value=s.Rational(A,B)*10**(exp-exp2)
                return constant(rf'Sebuah data berukuran ${A}\times10^{exp}$ byte dibagi rata menjadi ${B}\times10^{exp2}$ bagian. Berapa byte tiap bagian? Jawaban dapat berupa bilangan biasa atau bentuk baku yang setara.',value,f'Bagi koefisien dan kurangkan pangkat: ({A}/{B})×10^({exp}-{exp2})={value}.','v2_bentuk_baku_pembagian',level)
            d=r.choice([2,3,5,6,7])
            if level=='easy':return constant(rf'Sederhanakan $\sqrt{{{A*A*d}}}$.',A*s.sqrt(d),f'Faktor kuadrat {A*A}: √({A*A}×{d})={A}√{d}.','v2_akar_sederhana',level)
            # Product and sum reconstruct positive radical coefficients.
            u=r.randint(2,8);v=r.randint(1,u-1)
            return checked(rf'Dua panjang p,q berbentuk kelipatan $\sqrt{{{d}}}$ positif, p>q, memenuhi $p+q={s.latex((u+v)*s.sqrt(d))}$ dan $pq={u*v*d}$. Tentukan $(p-q)/(\sqrt{{{d}}})$.',u-v,f'Misalkan p=a√{d}, q=b√{d}. Maka a+b={u+v}, ab={u*v}. Akar memberi a={u}, b={v} karena p>q. Hasil a-b={u-v}.','v2_akar_rekonstruksi_panjang',level,system(['a','b'],[a+b-u-v,a*b-u*v],a-b,[a-b,b]))
        if bab==2:
            k=r.randint(2,12);legs=(3*k,4*k);hyp=5*k
            if code=='E':return constant(f'Titik A{pair(A,B)} dan B{pair(A+3*k,B+4*k)} diberikan. Berapa jarak AB?',hyp,f'Selisih koordinat {3*k},{4*k}; jarak √(({3*k})²+({4*k})²)={hyp}.','v2_jarak_pythagoras',level)
            if code=='C':return constant(f'Segitiga siku-siku sama kaki memiliki hipotenusa {m(k*s.sqrt(2))} cm. Berapa luas segitiga?',s.Rational(k*k,2),f'Masing-masing kaki {k} cm; luas 1/2×{k}²={s.Rational(k*k,2)}.','v2_segitiga_istimewa_luas',level)
            extra=r.randint(2,7)
            return checked(f'Segitiga siku-siku memiliki selisih kedua kaki {k} cm dan hipotenusa {hyp} cm. Pada setiap sisi segitiga dipasang pita, tetapi pada tiap sudut dua ujung pita bertumpuk sepanjang {extra} cm per sudut. Berapa total panjang pita sebelum ditumpangkan?',12*k+3*extra,f'Kaki kecil x, besar x+{k}. Pythagoras x²+(x+{k})²={hyp*hyp} memberi akar positif x={3*k}; kaki lain {4*k}. Keliling {12*k}. Tambahkan tiga tumpang tindih {extra} cm: {12*k+3*extra}.','v2_pythagoras_dimensi_pita',level,system(['a','b'],[a*a+b*b-hyp*hyp,b-a-k],a+b+hyp+3*extra,[a,b]))
        if bab==3:
            rate=A*1000;fixed=B*1000;budget=rate*U+fixed;fee=C*1000
            if level=='medium':return constant(f'Sewa alat berbiaya tetap {fixed} rupiah dan {rate} rupiah per jam penuh. Dengan dana {budget} rupiah, berapa jam penuh terbanyak?',U,f'Pertidaksamaan {fixed}+{rate}t≤{budget}; maka t≤{U}.','v2_ptlsv_anggaran',level)
            if code=='C':
                return checked(f'Paket A berbiaya {A}x+{B} ribu rupiah, paket B {A+C}x+{B+C*U} ribu rupiah. Toko memberi potongan tetap {2*C*U} ribu rupiah hanya pada B. Untuk x bilangan bulat positif, berapa x terbesar agar B setelah potongan lebih murah daripada A?',U-1,f'Bandingkan ({A+C})x+{B+C*U}-{2*C*U}<{A}x+{B}, jadi {C}x<{C*U}, x<{U}. Batas bulat positif {U-1}.','v2_ptlsv_model_perbandingan',level,finite(['x'],[[1,2*U]],[s.Piecewise((0,C*x<C*U),(1,True))],x,'max'))
            p=r.randint(3,6);d=r.randint(2,4);k=r.randint(8,20);t=r.randint(1,3);later=k+p*t;early=k-d*t;fixed=r.randint(50,100);flat=fixed+p*early;upper=later+5;costB=s.Piecewise((flat,x<=k),(flat+(p+d)*(x-k),True));values=[j for j in [early,later] if j>0]
            return checked(f'Layanan A berbiaya {fixed} ribu rupiah ditambah {p} ribu per menit. Layanan B berbiaya tetap {flat} ribu untuk durasi sampai {k} menit, kemudian tambahan {p+d} ribu per menit yang melebihi {k}. Tentukan jumlah seluruh durasi bulat positif x≤{upper} menit yang membuat kedua biaya sama.',sum(values),f'Pisahkan kasus x≤{k} dan x>{k}. Kasus pertama: {fixed}+{p}x={flat}, memberi x={early}; terima hanya jika positif dan dalam interval. Kasus kedua: {fixed}+{p}x={flat}+{p+d}(x-{k}), memberi x={later}. Kandidat sah {values}; jumlah {sum(values)}.','v2_plsv_dua_regim_biaya',level,finite(['x'],[[1,upper]],[fixed+p*x-costB],x,'sum'))
        if bab==4:
            n=r.randint(4,6)
            if code=='C':
                if level=='easy':return constant(f'Himpunan A memiliki {n} anggota. Dalam korespondensi satu-satu A ke B, berapa banyak anggota B?',n,'Korespondensi satu-satu memasangkan setiap anggota tepat satu kali, sehingga banyak anggota sama.','v2_bijeksi_kardinal',level)
                forbidden=[(0,0),(1,1),(2,2)];label=r.randint(10,99);cert={'type':'restricted_bijection','size':n,'forbidden':forbidden};value=solve_certificate(cert)
                return checked(f'Pada lemari nomor {label}, ada {n} siswa bernomor 1 sampai {n} dan {n} loker bernomor sama. Setiap siswa mendapat satu loker berbeda. Siswa 1,2,3 masing-masing dilarang memakai loker bernomor dirinya. Berapa korespondensi satu-satu yang diperbolehkan?',value,f'Inklusi-eksklusi: n!−3(n−1)!+3(n−2)!−(n−3)!. Untuk n={n}, hasil {value}; siswa lain tidak memiliki larangan.','v2_bijeksi_larangan_beririsan',level,cert)
            lo=r.randint(1,4);hi=lo+r.randint(5,9);offset=r.randint(1,4);left=list(range(lo,hi+1));right=list(range(lo+offset,hi+offset+1));counts=[sum(v%u==0 and v>u for v in right) for u in left];value=sum(counts)
